<?php

namespace Splicewire\Beam\Threads\Config;

use Schemastud\DataSchemas\Attributes\Description;
use Schemastud\DataSchemas\Attributes\MapValues;
use Schemastud\DataSchemas\Attributes\Title;
use Splicewire\Beam\Config\Attributes\ConfigKey;
use Splicewire\Beam\Config\Attributes\ConfigRoot;
use Splicewire\Beam\Config\ConfigSection;

/**
 * The `beam.threads` Config Section (ADR-0245), generated by `splicewire:beam:make:config-section` from config/beam/threads.php.
 *
 * Every key is deploy-only and not overridable until it is opted in.
 */
#[ConfigRoot(root: 'beam.threads', title: 'Threads', description: 'The driver, participant vocabulary and sidecar model bindings for the multi-participant thread particle.')]
class BeamThreadsSection extends ConfigSection
{
    public function __construct(
        #[Title('Turn driver'), Description('The strategy that advances a thread from one turn to the next. Left null, a thread is a passive, participant-driven surface with no automated turn-taking; a host tier binds its own driver here. This package ships no AI driver.'), ConfigKey]
        public mixed $turn_driver,
        #[Title('Participant morph map'), Description('The concrete model class each participant alias resolves to. The keys are the durable morph tokens a thread\'s participants and messages store; the values are overridable so a host can point an alias at its own model.'), ConfigKey]
        public BeamThreadsMorphMapConfig $morph_map,
        #[Title('Sidecar models'), Description('The host model classes that store a message\'s media and embeddings, which stay outside the JSON payload and are surfaced through the message references projection.'), ConfigKey]
        public BeamThreadsSidecarConfig $sidecar,
        #[Title('Table name overrides'), Description('Per-table name overrides keyed by table stem (threads, messages, participants). Each value is a full table name, prefix included, since it overrides the Beam::tableFor seam rather than feeding it. Null — the default — leaves every table resolving through the beam.core.table_prefix seam to its package name. This package ships this key as null (no overrides); a host that wants an override publishes the config and replaces the null with a map. Null means no overrides.'), ConfigKey, MapValues('string')]
        public ?array $tables = null,
    ) {}
}
